/**
 * @description Records for the payload preview: finds the record (Id, or the value of the object's name field, e.g.
 * Case Number, Account Name or an auto number), names it, and builds
 * the inbound sample: the call the middleware must make, with a body filled from a record or a template without values.
 * @group Integration Hub
 */
public with sharing class IntegrationHubPreviewSample {

    private static final List<String> CASE_FIELDS = new List<String>{ 'Subject', 'Origin', 'Status', 'Priority', 'AccountId', 'ContactId' };
    private static final Set<String> SKIP_FIELDS = new Set<String>{ 'Id', 'OwnerId', 'RecordTypeId' };
    private static final Integer SAMPLE_FIELDS = 10;

    /**
     * @description Describe of an object by API name.
     * @param objectName the API name (may be blank)
     * @return the describe, or null when the object does not exist
     */
    public static Schema.DescribeSObjectResult describe(String objectName) {
        Schema.SObjectType objectType = String.isBlank(objectName) ? null : Schema.getGlobalDescribe().get(objectName.trim());
        return objectType == null ? null : objectType.getDescribe(SObjectDescribeOptions.DEFERRED);
    }

    /**
     * @description Finds a record by Id, or by the object's name field (Name, Case Number, an auto number, ...). Works
     * for any object, standard or custom. Reads in system mode.
     * @param d the object describe (may be null)
     * @param input the record Id or name (may be blank)
     * @return the record with Id and its name field, or null when not found
     */
    public static SObject findRecord(Schema.DescribeSObjectResult d, String input) {
        if (d == null || String.isBlank(input)) {
            return null;
        }
        String nameField = nameFieldOf(d);
        String soql = 'SELECT Id' + (nameField == null ? '' : ', ' + nameField) + ' FROM ' + d.getName() + ' WHERE ';
        Id asId = toId(input);
        if (asId != null) {
            return IntegrationHubData.queryFirst(soql + 'Id = :v LIMIT 1', new Map<String, Object>{ 'v' => asId });
        }
        return nameField == null
            ? null
            : IntegrationHubData.queryFirst(soql + nameField + ' = :v LIMIT 1', new Map<String, Object>{ 'v' => input.trim() });
    }

    /**
     * @description A short label of a record: object label and its name (Case Number for a Case).
     * @param rec the record found by findRecord
     * @return e.g. "Case 00001026"
     */
    public static String labelOf(SObject rec) {
        Schema.DescribeSObjectResult d = rec.getSObjectType().getDescribe(SObjectDescribeOptions.DEFERRED);
        String nameField = nameFieldOf(d);
        Object name = nameField == null ? null : rec.get(nameField);
        return d.getLabel() + ' ' + (name == null ? String.valueOf(rec.Id) : String.valueOf(name));
    }

    /**
     * @description Fills an inbound preview: POST to the event's REST path with the inbound headers and a body
     * {"fields": {...}} from the record, or a template without values when no record is given.
     * @param p the preview to fill
     * @param ev the inbound event
     * @param input a record Id or name, or blank
     */
    public static void inbound(IntegrationHubPreview.Preview p, IH_Event__c ev, String input) {
        p.method = 'POST';
        p.url = IntegrationHubPreview.REST_BASE + ev.Event_Key__c;
        p.headers = new List<IntegrationHubPreview.Header>{
            new IntegrationHubPreview.Header('Authorization', 'Bearer <token of the Inbound User>'),
            new IntegrationHubPreview.Header('Content-Type', 'application/json'),
            new IntegrationHubPreview.Header('X-Request-Id', '<unique per request>')
        };
        Id asId = toId(input);
        Schema.DescribeSObjectResult d = String.isBlank(ev.Related_Object__c) && asId != null
            ? asId.getSObjectType().getDescribe(SObjectDescribeOptions.DEFERRED) : describe(ev.Related_Object__c);
        if (d == null) {
            p.body = JSON.serializePretty(new Map<String, Object>{ 'fields' => new Map<String, Object>() });
            p.bodySource = 'Template';
            p.message = String.isBlank(input) ? null : 'Set Related Object on the event, or enter a record Id.';
            return;
        }
        List<String> fields = sampleFields(d);
        if (String.isBlank(input)) {
            p.body = JSON.serializePretty(new Map<String, Object>{ 'fields' => valuesOf(null, fields, true) });
            p.bodySource = 'Template for ' + d.getLabel();
            return;
        }
        SObject rec = findRecord(d, input);
        if (rec == null) {
            p.message = 'No ' + d.getLabel() + ' record found for "' + input + '".';
            return;
        }
        SObject full = IntegrationHubData.queryFirst('SELECT ' + (fields.isEmpty() ? 'Id' : String.join(fields, ', ')) + ' FROM ' + d.getName() + ' WHERE Id = :id LIMIT 1',
            new Map<String, Object>{ 'id' => rec.Id });
        p.recordLabel = labelOf(rec);
        p.body = JSON.serializePretty(new Map<String, Object>{ 'fields' => valuesOf(full, fields, d.getName() == 'Case') });
        p.bodySource = 'Sample from ' + p.recordLabel;
    }

    /**
     * @description The fields of the inbound sample: the usual Case fields, or up to 10 fields a user can fill.
     * @param d the object describe
     * @return the field API names
     */
    @TestVisible
    private static List<String> sampleFields(Schema.DescribeSObjectResult d) {
        if (d.getName() == 'Case') {
            return CASE_FIELDS;
        }
        List<String> names = new List<String>();
        for (Schema.SObjectField f : d.fields.getMap().values()) {
            Schema.DescribeFieldResult fd = f.getDescribe();
            Boolean usable = fd.isCreateable() && !SKIP_FIELDS.contains(fd.getName()) && fd.getType() != Schema.DisplayType.BASE64;
            if (usable && fd.isNameField()) {
                names.add(0, fd.getName());
            } else if (usable) {
                names.add(fd.getName());
            }
        }
        while (names.size() > SAMPLE_FIELDS) {
            names.remove(names.size() - 1);
        }
        return names;
    }

    private static Map<String, Object> valuesOf(SObject rec, List<String> fields, Boolean keepEmpty) {
        Map<String, Object> values = new Map<String, Object>();
        for (String field : fields) {
            Object value = rec == null ? null : rec.get(field);
            if (value != null || keepEmpty) {
                values.put(field, value);
            }
        }
        return values;
    }

    private static String nameFieldOf(Schema.DescribeSObjectResult d) {
        for (Schema.SObjectField f : d.fields.getMap().values()) {
            Schema.DescribeFieldResult fd = f.getDescribe();
            if (fd.isNameField()) {
                return fd.getName();
            }
        }
        return null;
    }

    private static Id toId(String value) {
        try {
            return String.isBlank(value) ? null : Id.valueOf(value.trim());
        } catch (StringException e) {
            return null;
        }
    }
}
